import{_ as e,c as i,o as l,af as r}from"./chunks/framework.BKeRpnBD.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"易经人生导航","text":"用 AI 解读卦象，用原典理解变化","tagline":"起卦、解卦、读经典、学六十四卦，把《易经》变成日常可用的智慧工具。","image":{"src":"/IChingStudy.png","alt":"I Ching: Yi Jing Life Guide App"}},"features":[{"title":"AI 解卦与追问","details":"围绕你的问题解读卦象、动爻与变化方向，帮助你整理决策、关系、时机与现实处境。"},{"title":"易经原典阅读","details":"集中阅读《周易》、易传、周易正义、高岛易断、焦氏易林等典籍，支持沉浸式阅读与繁简切换。"},{"title":"4096 变化关系","details":"探索 64×64 种本卦到之卦的变化网络，看见动爻如何改变局势，而不只停留在单次结果。"},{"title":"课程与测验","details":"用结构化课程、卦名练习、卦辞与爻辞测验，把零散认识逐步变成稳定理解。"}]},"headers":[],"relativePath":"zh/index.md","filePath":"zh/index.md"}'),t={name:"zh/index.md"};function n(h,a,o,s,p,d){return l(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="不只是占卦-更是一套易学系统" tabindex="-1">不只是占卦，更是一套易学系统 <a class="header-anchor" href="#不只是占卦-更是一套易学系统" aria-label="Permalink to “不只是占卦，更是一套易学系统”">​</a></h2><p>《I Ching: Yi Jing Life Guide》将易经占问、AI 解读、古籍阅读、卦象学习、变化网络、课程与测验放在同一个 App 里。你可以在遇到问题时快速起卦，也可以长期研读《周易》与重要易学典籍，逐步建立自己的判断力。</p><p>如果你搜索的是“易经 App”、“周易学习”、“六十四卦查询”、“AI 解卦”、“I Ching app”或“Book of Changes”，这款 App 的设计目标不是给你一句神秘答案，而是让你看见卦象背后的结构、语境与可行方向。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><ul><li><strong>AI 卦象解读</strong>：输入你的问题，从卦义、动爻、之卦与现实处境多角度理解。</li><li><strong>多种起卦方式</strong>：支持大衍、铜钱、一爻成卦、高岛略筮等练习方式。</li><li><strong>古籍典藏阅读</strong>：阅读常用易学典籍，支持阅读进度保存、字号、排版、文字颜色与繁简切换。</li><li><strong>六十四卦学习</strong>：查询卦辞、象辞、爻辞与卦象结构，理解每一卦如何成立。</li><li><strong>4096 变化网络</strong>：查看本卦到之卦的完整变化关系，快速定位动爻与转化模式。</li><li><strong>课程、测验、收藏与笔记</strong>：用长期学习方式掌握易经，不只依赖单次占问。</li></ul><h2 id="适合谁使用" tabindex="-1">适合谁使用？ <a class="header-anchor" href="#适合谁使用" aria-label="Permalink to “适合谁使用？”">​</a></h2><ul><li>想用《易经》辅助自我反思与决策的人</li><li>想系统学习六十四卦、卦辞、爻辞的人</li><li>想阅读易学原典与后世注解的人</li><li>想把 AI 解读作为学习工具，而不是迷信答案的人</li><li>想建立长期易学笔记与收藏系统的人</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="这是占卜-app-吗" tabindex="-1">这是占卜 App 吗？ <a class="header-anchor" href="#这是占卜-app-吗" aria-label="Permalink to “这是占卜 App 吗？”">​</a></h3><p>它可以起卦与解卦，但定位不只是占卜。它更像一个“易经学习与思考工具”，帮助你从卦象、原典和变化关系中整理问题。</p><h3 id="初学者能用吗" tabindex="-1">初学者能用吗？ <a class="header-anchor" href="#初学者能用吗" aria-label="Permalink to “初学者能用吗？”">​</a></h3><p>可以。App 提供 AI 解释、课程、测验和卦象查询，适合从零开始理解六十四卦。</p><h3 id="进阶学习者能用吗" tabindex="-1">进阶学习者能用吗？ <a class="header-anchor" href="#进阶学习者能用吗" aria-label="Permalink to “进阶学习者能用吗？”">​</a></h3><p>可以。原典阅读、4096 变化关系、焦氏易林与高岛易断等内容，更适合长期研读与对照。</p><h3 id="会保存我的问题吗" tabindex="-1">会保存我的问题吗？ <a class="header-anchor" href="#会保存我的问题吗" aria-label="Permalink to “会保存我的问题吗？”">​</a></h3><p>App 强调专注学习与个人反思。你可以在 App 内保存自己的收藏、笔记和阅读进度。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to “下载”">​</a></h2><p>在 App Store 下载 <strong>I Ching: Yi Jing Life Guide</strong>，把《易经》变成可以每天学习、查询与反思的工具。</p>',18)])])}const f=e(t,[["render",n]]);export{g as __pageData,f as default};
